def compute(vars):
    owned_facilities = vars["v1"]
    total_facilities = vars["v2"]

    if total_facilities == 0:
        return None

    ratio = owned_facilities / total_facilities
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "owned_facilities": owned_facilities,
            "total_facilities": total_facilities,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
